(function () {
'use strict';
function boot() {
var U = window.U;
var Tools = window.Tools || {};
var RV = window.ToolCore && window.ToolCore.ResultView;
var form = document.getElementById('pctForm');
if (!form || !U || !Tools.percentage || !RV) return;
var $ = function (id) { return document.getElementById(id); };
var lastCopy = '';
var LABELS = {
share: ['数值 A', '数值 B（整体）', '占比'],
growth: ['原值 A', '新值 B', '增长率'],
value: ['百分比 X（%）', '基准值 B', '百分比值'],
restore: ['变化率 r（%，正为增长）', '变化后的值 B', '还原原值 A'],
points: ['百分比 A（%）', '百分比 B（%）', '百分点差'],
};
function status(message, isError) {
$('pct-status').textContent = message || '';
$('pct-status').hidden = !message;
$('pct-status').classList.toggle('is-error', !!isError);
}
function syncLabels() {
var mode = $('pct-mode').value;
var labels = LABELS[mode];
$('pct-l1').textContent = labels[0];
$('pct-l2').textContent = labels[1];
$('pct-rlabel').textContent = labels[2];
}
function copyText(text) {
if (navigator.clipboard && navigator.clipboard.writeText) {
return navigator.clipboard.writeText(text).then(function () { return true; }, function () { return false; });
}
return new Promise(function (resolve) {
var input = document.createElement('textarea');
input.value = text;
input.setAttribute('readonly', '');
input.style.position = 'fixed';
input.style.opacity = '0';
document.body.appendChild(input);
input.select();
var ok = false;
try { ok = document.execCommand('copy'); } catch (error) { ok = false; }
document.body.removeChild(input);
resolve(ok);
});
}
function clearResult() {
$('pct-result').hidden = true;
$('pct-rvalue').textContent = '--';
RV.clear($('pct-detail'));
RV.clear($('pct-explain'));
lastCopy = '';
}
form.addEventListener('submit', function (event) {
event.preventDefault();
var mode = $('pct-mode').value;
var result = Tools.percentage.calculate({ mode: mode, a: $('pct-a').value, b: $('pct-b').value });
RV.renderError($('pct-error'), result);
if (result.status !== 'success') {
clearResult();
status(result.errors.join('；'), true);
return;
}
var value = result.metrics.value;
$('pct-rvalue').textContent = String(value) + (result.metrics.unit ? ' ' + result.metrics.unit : '');
RV.renderDetails($('pct-detail'), result.details);
RV.renderExplanation($('pct-explain'), result);
$('pct-result').hidden = false;
lastCopy = String(value) + (result.metrics.unit ? ' ' + result.metrics.unit : '');
status('计算完成；可复制完整精度结果。');
U.track('calc_result', { tool: 'percentage', mode: mode, success: true });
});
$('pct-mode').addEventListener('change', function () {
syncLabels();
clearResult();
$('pct-error').hidden = true;
status('');
});
$('pct-copy').addEventListener('click', function () {
if (!lastCopy) return;
copyText(lastCopy).then(function (ok) {
$('pct-copy').textContent = ok ? '已复制完整精度' : '复制失败，请手动选择';
setTimeout(function () { $('pct-copy').textContent = '复制完整精度'; }, 1800);
});
});
syncLabels();
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})();
